                { "Mothballs are poison that smells of grandma. The kind of crime nobody calls a crime.", curta = "Mothballs: poison that smells of granny." },
                { "I deduced someone moved the book. The dust told me. Dust always tells." },
                { "I found out a book on this shelf has money inside. I won't say which. Silverfish have ethics too." },
                -- fim das novas
            },
            lentes = { "a crime scene", "an interrogation without a lawyer", "a case closed too soon" },
            fechos = { "Noted.", "The culprit always returns to the bookcase.", "Nobody leaves this house without explaining." },
