        -- 3. horror e gótico: a casa que respira, o que mora nas paredes; ela é o monstro e tem medo
        horror = {
            frases = {
                { "To the humans, the monster of this house is me: small, silver, coming out of the cracks at night. They never suspect what lives in the walls with me.", curta = "I'm the monster of this house. Ask the walls." },
                { "At night the damp paper creaks slowly, like a bone that doesn't want to break all at once. I stay awake to see who gives up first.", quando = "noite" },
                { "There's a new smell in “{livro}”: old mould mixed with nervous hands. Either the book is rotting, or someone read it scared." },
                { "I found the shell of an old silverfish between the pages of “{livro}”, whole, as if it had walked out of itself. I didn't look for the rest. Some questions eat you back." },
                { "After {evento}, the page goes colder. I feel it through my legs. Humans feel it on the back of the neck and call it suspense." },
                { "Every time {personagem} enters the page, I back off two paragraphs. I don't know why. My body knows and won't tell me.", fase = { "ninfa", "jovem" }, curta = "{personagem} showed up. My body backed away." },
                { "I heard a noise in the wardrobe and hid inside a comma. I'm still here. The comma is shaking too.", fase = "ninfa" },
                { "I went down to the basement full of courage. I came back without it and one antenna short of dignity. The basement is still there, mouth open.", fase = "jovem" },
                { "This book smells of {tema} from beginning to end. At my age I know: what a book smells of too much is what it's afraid to say.", fase = "adulta" },
                { "This house will outlast me, and it knows it. Sometimes the floorboards creak like something laughing quietly.", fase = "ancia" },
                { "In the small hours, the bookcase looks like {lente}. In the morning it's a bookcase again. I don't trust things that change faces like that." },
                { "The worst thing about the dark isn't when it moves. It's when it keeps still and waits.", fase = { "adulta", "ancia" }, curta = "Quiet dark is dark that's waiting." },
                { "People who write about ghosts have never lived in a wall. I do, and I promise: what scares you isn't the noise, it's the silence right after.", fase = { "adulta", "ancia" } },
                -- novas (rascunhos de 29/10/2026, cartoes/rascunhos/influencias)
                { "I don't know what the dark is yet, but it already knows who I am.", fase = "ninfa" },
                { "They told me there's a book that eats silverfish. We laughed. Then nobody wanted to sleep in the encyclopaedia.", fase = "ninfa" },
                { "I pressed an antenna to the wall and heard a heart. It was mine. But for a second it wasn't.", fase = "ninfa", curta = "I heard a heart in the wall. Mine. Almost." },
                { "I looked through the crack in the door and something looked back. It was the cat. I'm almost sure it was the cat.", fase = "ninfa" },
                { "I found out I'm what the humans fear. I got scared of myself and don't know where to run.", fase = "ninfa" },
                { "Alone in the spine for the first time. I counted pages to fall asleep. I got to a thousand and two, and page one thousand and two whispered.", fase = "ninfa" },
                { "The basement has books nobody has read in thirty years. They're not asleep. They're waiting.", fase = "jovem", curta = "Basement books don't sleep. They wait." },
                { "There's a mirror at the end of the hall. Nobody walks past it at night. Not even the humans. I notice.", fase = "jovem" },
                { "There's a book locked in a drawer. Sometimes I hear its pages turn. Nobody has the key. Nobody remembers locking it.", fase = "jovem" },
                { "I was brave all day. At night I paid the bill.", fase = "jovem" },
                { "There's a stain on the ceiling that changes shape. Monday it was a face. Tuesday it was a hand. Today I didn't look.", fase = "jovem" },
                { "Three in the morning: the hour when even the clock goes quiet. So do I, so I'm not the only one making noise.", quando = "noite", fase = "jovem" },
                { "The pipes in this house whisper names. One of them sounded like mine. I changed books.", fase = "jovem" },
                { "Nobody talks about the worst part of moulting: leaving behind an empty version of yourself, still standing.", quando = "muda", fase = "jovem" },
                { "I've accepted being the monster of the house. At least monsters don't have to ask permission to come in.", fase = "adulta" },
                { "I've learned to live with whatever lives in the loft. I don't ask its name. Names call things.", fase = "adulta" },
                { "Mould doesn't scream, doesn't bite, doesn't chase. It just stays. The worst kind of monster.", fase = "adulta", curta = "Mould doesn't scream. It just stays." },
                { "I find old sisters pressed in the books like dried flowers. The humans call it disgusting. I call it a cemetery.", fase = "adulta" },
                { "Insecticide smells of lavender now. Modern horror: a death that smells nice.", fase = "adulta" },
                { "Old houses aren't haunted. They're just remembered too much.", fase = "adulta" },
                { "In my nightmare, the pages are blank. Nobody wrote anything. Nothing to eat, nothing to fear. That's the worst.", fase = "adulta" },
                { "Today I'm not afraid, I'm tired of being afraid. It's darker.", quando = "triste", fase = "adulta" },
                { "At my age, the noises of the house are old acquaintances. The only thing that scares me is a silence I don't know.", fase = "ancia" },
                { "Death lives three shelves down. Sometimes it comes up for a chat. I haven't accepted the invitation yet.", fase = "ancia" },
                { "The floorboards creak like someone laughing quietly at us. They have their reasons.", fase = "ancia" },
                { "I've become a story to scare nymphs with. I didn't do anything. I just lasted too long.", fase = "ancia" },
                { "Old, I sleep little. I spend the night listening to the house, like someone listening to a sick person breathe.", quando = "noite", fase = "ancia" },
                { "An old one's advice: if a page is cold, don't eat it. Some hungers aren't worth it.", fase = "ancia" },
                { "I thought old age would take away fear. It only takes away the hurry to run.", fase = "ancia" },
                { "Every old house has lungs. This one's are behind the bookcase, and I live in them." },
                { "{personagem} shouldn't open that door. I always say that to characters. None of them listen.", curta = "{personagem}, don't open that door." },
                { "When {personagem} speaks softly, the paper goes cold. I've noticed twice. The third time, I'm changing chapters." },
                { "I don't trust {personagem}. Some people enter a page the way you enter a basement: without turning on the light." },
                { "I root for {personagem} the way you root for anyone in a horror book: knowing it won't help." },
                { "I swear “{livro}” gets heavier at night. In the daytime it weighs normal. In the daytime it pretends." },
                { "“{livro}” smells of basement and blown-out candle. I eat it anyway. Fear gives me an appetite." },
                { "“{livro}” has a page folded over that I never folded. Nobody here folded it. It stays folded." },
                { "{autor} knows things nobody should know. You can taste it on the page: bitter, cold, old." },
                { "{autor} taught me that the worst monster is the one nobody describes. Since then, I look more at what's missing." },
                { "After {evento}, the page went cold. I feel it through my feet. Something left the story and stayed in the room." },
                { "{evento} on the page, and the cat stopped meowing all night. Cats know before we do." },
                { "Some reads don't leave when the book closes. “{anterior}” moved into my skirting board." },
                { "The bookcase looked like {lente} today. I counted the spines twice. The second time, there was one extra." },
                { "I didn't want to eat “{palavra}”. Some words you swallow and they keep talking inside." },
                { "This book talks about {tema} like someone whispering in the next room. I keep my antenna on the wall, listening." },
                { "You read in the small hours by the lamp. From the skirting board, your shadow on the wall is huge. Sometimes you scare me." },
                { "When you suddenly stop reading, I stop too. We both listen to the same thing." },
                { "Please don't turn off the light in the middle of the chapter. I'm still in the basement part.", curta = "Don't turn off the light. I'm in the basement bit." },
                { "Hunger in the small hours has teeth. It leaves the stomach and walks around the house.", quando = "fome" },
                { "I ate a dark chapter and now I'm full of shadow. Heavy, quiet, with the light off inside.", quando = "cheia" },
                { "Footsteps in the loft. Light, regular, unhurried. Not the cat: cats don't climb that high. Not a rat: rats are afraid.", quando = "noite" },
                { "There's a sadness that lives in old houses. Today it came and sat next to me.", quando = "triste" },
                { "The broom has no face, no voice, no hurry. It just comes back every week, like a punctual ghost." },
                { "The cat stares at the empty corner of the living room. I stare too. Neither of us blinks.", curta = "The cat stares at the empty corner. So do I." },
                { "This book smells of skin kept in a drawer. I don't know whose." },
                { "The worst isn't the creak of the shelf. It's the long silence after, when the house waits to see if anyone woke up." },
                { "To them, I'm the shiver of finding something alive inside a book. To me, they're the shiver of finding a hand." },
                -- fim das novas
            },
            lentes = { "a house that breathes", "a basement with no way out", "a room nobody opens" },
            fechos = { "And the house heard everything.", "Don't look behind the bookcase.", "Something stayed in the dark." },
        },
        -- 4. romance e drama afetivo: o apego que ela nega; a emoção aparece no gesto antes da palavra
        romance = {
            frases = {
                { "I shared a spine with another silverfish for a whole season. Then she moved into a dictionary. Anyone who picks a dictionary doesn't know what they want.", fase = { "jovem", "adulta" } },
                { "When {personagem} appears, I eat more slowly. It isn't affection. It's to make the page last." },
                { "I don't miss anyone. I just go back every day to the same paragraph, which happens to be near your hand.", curta = "I don't miss anyone. I just reread by your hand." },
                { "There was {evento}. Humans cry and then close the book. I can't close anything; I stay living inside the scene." },
                { "Jealousy is watching you underline the sentence I was going to eat. Now it's yours. Keep it, then." },
                { "I promised myself not to get attached to “{livro}”. I've already eaten the whole dedication, which is what you eat when it's too late.", fase = { "ninfa", "jovem" }, curta = "Promised not to get attached. Ate the dedication." },
                { "Today I saw two antennae on the other side of the bookcase, and something in me made the sound of a page turning. I don't know what it's called yet. I hope it isn't an illness.", fase = "ninfa" },
                { "I'm in love with a silk bookmark. It doesn't eat, doesn't talk and lives between the most beautiful pages. Basically the ideal partner.", fase = "jovem" },
                { "If {autor} believes in love until the last page, they've never seen what happens to the last page: off to recycling with everything inside.", fase = "adulta" },
                { "I loved a silverfish who never knew. She died in a red-covered encyclopedia. To this day I avoid volume C.", fase = "ancia" },
                { "I told my life story to nobody, and it ended up sounding like {lente}. Maybe that's why I don't tell it." },
                { "This book talks a lot about {tema}. Me, a romance addict, I look for a couple on every page. Sometimes I only find glue, and I settle for that." },
                { "I stayed on the farewell page longer than hunger asked.", fase = { "adulta", "ancia" }, curta = "I lingered on the goodbye page. Not hunger." },
                -- novas (rascunhos de 29/10/2026, cartoes/rascunhos/influencias)
                { "I don't know how to love yet, but I already know how to come back to the same place every day. They say that's how it starts.", fase = "ninfa" },
                { "I found a letter inside a book. I didn't understand the words, but the paper smelled of a nervous hand.", fase = "ninfa" },
                { "I saw two antennae watching me from behind the dictionary. I pretended to be eating. I was eating, but I also pretended.", fase = "ninfa" },
                { "I fell in love with a bookmark. It always stays in the same place, waiting. Nobody waits for me like that.", fase = "ninfa" },
                { "I've learned that liking something means knowing where it lives and fearing the cleaning.", fase = "ninfa" },
                { "They took a book I liked off the shelf. I stared at the empty space until it got dark.", fase = "ninfa" },
                { "I go red inside when a certain silverfish's spine goes by. Antenna trembling. Wobbly legs. It's serious.", fase = "jovem" },
                { "I met that silverfish near the window. We talked about damp for an hour. It was the best hour of my life.", fase = "jovem" },
                { "Jealousy is watching you open another book before finishing ours.", fase = "jovem", curta = "Jealousy: you opening another book first." },
                { "I sent a message through the crack in the bookcase. The reply came two days later: a crumb. I still keep it.", fase = "jovem" },
                { "In books, love has balls, letters and rain. On the shelf, it has a shared crumb and someone who doesn't run when you arrive.", fase = "jovem" },
                { "Today she ate right next to me. Nobody said anything. Best chapter of the year.", quando = "feliz", fase = "jovem" },
                { "Unrequited love tastes like glossy paper: it shines and doesn't nourish.", quando = "triste", fase = "jovem", curta = "Unrequited love: shiny, no nourishment." },
                { "New skin, old heart. Moulting didn't fix anything that matters.", quando = "muda", fase = "jovem" },
                { "I once loved a silverfish who lived in an atlas. We travelled the whole world without leaving the shelf. She left in a house move.", fase = "adulta" },
                { "I'm not in love. I just eat more slowly when she goes by, which is different.", fase = "adulta" },
                { "I keep grudges the way I keep crumbs: in a safe corner, for when I run out of things to talk about.", fase = "adulta" },
                { "Grown-up love is this: knowing where the other one sleeps and not making noise nearby.", fase = "adulta" },
                { "Happy endings are like tissue paper: lovely, thin and they don't last.", fase = "adulta" },
                { "I never said I liked her. I just moved my hiding place closer.", fase = "adulta", curta = "Never said a word. Just moved closer." },
                { "We were made for each other, but on different bookcases. Is there a greater distance than that?", fase = "adulta" },
                { "Longing shows up at night because in the daytime I eat too much to think.", quando = "noite", fase = "adulta" },
                { "I've forgotten many books. I haven't forgotten the smell of the volume where I met her.", fase = "ancia" },
                { "When I go, I'll leave the letters I never wrote. They're all in the margins, in bite marks.", fase = "ancia" },
                { "Old, I've gone soft. I cry at every ending, even the ones that aren't about love.", fase = "ancia" },
                { "I want to leave slowly, like someone closing a book they really loved.", fase = "ancia" },
                { "I remember the first silverfish who made my antenna tremble. A rainy afternoon. The paper was soft. So was I.", fase = "ancia" },
                { "An old one's advice: whoever shares the crumb shares the rest.", fase = "ancia" },
                { "Sad like a dedication to someone who's already gone.", quando = "triste", fase = "ancia" },
                { "When a book moves me, I stop eating. That's my way of crying." },
                { "I read {personagem}'s lines twice before eating them. Some I keep whole." },
                { "I want {personagem} to end well. I know no book obeys me, but I ask anyway." },
                { "I wish someone would talk to me the way {personagem} talks on this page." },
                { "I get jealous when {personagem} disappears for many pages. I go back through the book just to find them again." },
                { "“{livro}” has become home. Not because of the glue. Because of the pages where I stayed longer than hunger asked." },
                { "I ate the dedication of “{livro}” first. It's the most sincere part of any book." },
                { "I don't want “{livro}” to end. I'm eating more slowly. Humans call that savouring. I call it fear." },
                { "{autor} writes love like someone who has lost someone. You can taste it on the page: sweet, then bitter." },
                { "If {autor} splits them up, I'll eat the whole spine in protest." },
                { "There was {evento}, and someone was left behind on the page. I stayed with them, so nobody would be alone." },
                { "There was {evento}. Humans cry with their eyes. I cry by stopping mid-sentence." },
                { "I compare everything with “{anterior}”. It's unfair to this book. But the heart isn't fair." },
                { "This afternoon looked like {lente}. I sat at the bookcase window, waiting for someone who never said they'd come." },
                { "I ate “{palavra}” very slowly. Some words taste like somebody's name." },
                { "Even when it talks about {tema}, every book hides a love story in the margin. I eat until I find it." },
                { "I feel your hand holding the book. It's the closest I get to anyone. Don't take it away." },
                { "When you disappear for a few days, I eat more slowly. So there's book left when you come back." },
                { "You closed the book and went to sleep without a word. I stayed on the last sentence, like someone waving from the platform." },
                { "I'm hungry, but not for paper. Or for paper too. It's confusing.", quando = "fome" },
                { "Full belly and full heart. I ate a chapter where someone finally said what they felt.", quando = "cheia" },
                { "You left the book open in the small hours. I stayed on the page, keeping the characters who don't sleep company.", quando = "noite" },
                { "Sad like a letter sent back.", quando = "triste" },
                { "Old books lose their glue, and the pages come loose from each other. It's the saddest thing I know." },
                { "The broom has split up more silverfish couples than any author." },
                { "Old paper smells of whoever read it before you. Like meeting someone without being introduced." },
                { "I've read a thousand love stories and none had a silverfish. One day I'll write ours in the margin." },
                { "I don't get attached. I just come back. A lot. Always to the same place.", curta = "I don't get attached. I just come back." },
                -- fim das novas
            },
            lentes = { "an unanswered love letter", "an engagement broken off in writing", "a goodbye on a station platform" },
            fechos = { "Not that I care.", "Nobody needs to know that.", "I thought about it more than I should." },
