        -- 6. ficção científica e distopia: sistema, vigilância, catálogo, extinção; registro frio
        ficcao = {
            frases = {
                { "In the future, books will be made of glass and light. We'll stare at them hungry, like someone at the window of a closed bakery.", fase = { "ninfa", "jovem" }, curta = "Future books: glass. Hunger behind the window." },
                { "They installed a device in the living room that blinks all night and listens to everything. Humans call it an assistant. I call it a permanent inquiry.", curta = "A light that blinks and listens. An inquiry." },
                { "“{livro}” has a barcode. I don't. The day they catalogue me, I'll know my species is either extinct or heritage." },
                { "The dehumidifier is a machine built to make my species impossible. Nobody apologised. Nobody even asked permission." },
                { "{autor} can imagine any future they like. I imagine a present without insecticide, and that's real science fiction." },
                { "I was born not knowing there was a system. Today I learned there is one, it keeps hours, and its hours are Saturday mornings.", fase = "ninfa" },
                { "I'm sure the vacuum cleaner learns. Yesterday it went straight to my corner. Today I changed corners. Tomorrow we'll see who evolves faster.", fase = "jovem" },
                { "There was {evento}, and the story carried on as if it were normal. That's how systems work: anything becomes normal if it happens every day.", fase = "adulta" },
                { "I've lived long enough to see paper become rare. The silverfish of the future will gnaw digital memories and starve well informed.", fase = "ancia" },
                { "I tried to see my life from the outside, as {lente}. Result: a tiny species, persecuted and very well catalogued by its enemies." },
                { "If {personagem} lived in this house, they'd have a number, a password and set reading hours. I only have the hours, and in secret." },
                { "This book treats {tema} like someone testing a machine. I read it like the part left over." },
                { "Progress has arrived: insecticide now smells of lavender.", fase = { "adulta", "ancia" }, curta = "Poison smells of lavender now. We've evolved." },
                -- novas (rascunhos de 29/10/2026, cartoes/rascunhos/influencias)
                { "I was born without a serial number. In this house everything has a barcode except me. I start out off the system.", fase = "ninfa" },
                { "I saw my first machine: a round robot that moves across the floor on its own and swallows everything. Humans call it a smart vacuum. I call it the end.", fase = "ninfa" },
                { "I found out I'm a living fossil. Humans keep fossils in museums. Me, they keep in traps.", fase = "ninfa" },
                { "There's a programme in this house and I'm not in it. I'll live in the gaps.", fase = "ninfa" },
                { "I asked my mother what the future would be like. She said: less paper. I wasn't hungry all night.", fase = "ninfa" },
                { "I learned the first law of the house: any light can be an eye.", fase = "ninfa", curta = "House law: any light may be an eye." },
                { "Every dystopia has a resistance. This house's lives in the skirting board and communicates by bites.", fase = "jovem" },
                { "I read the robot vacuum's manual. It learns the map of the house. Now I'm learning its map too.", fase = "jovem" },
                { "The vacuum goes over the same spots, in the same order, every day. I worked out the pattern. I live in the only spot it can't reach.", fase = "jovem" },
                { "Screens glow and have no smell. For a silverfish, the perfect nightmare: a book you can't eat.", fase = "jovem", curta = "A screen: a book you can't eat." },
                { "If evolution is fair, my granddaughters will gnaw on data cables.", fase = "jovem" },
                { "The blue light on the router blinks all night, like an artificial heart. I sleep to its rhythm without meaning to.", quando = "noite", fase = "jovem" },
                { "There was a power cut for an hour! The machines stopped. For an hour, the house belonged to the silverfish.", quando = "feliz", fase = "jovem" },
                { "Moult complete. New version, same hardware, same hunger.", quando = "muda", fase = "jovem", curta = "Moult done. New version, same hunger." },
                { "Station report: humidity below ideal, paper in decline, enemies on the rise. Forecast: survive anyway.", fase = "adulta" },
                { "I was catalogued once: photographed, identified and posted online with people asking what bug it was. I became data.", fase = "adulta" },
                { "We're the last readers of paper. When the last book is digitised, our world ends, and nobody will notice.", fase = "adulta" },
                { "The voice assistant hears everything. I keep absolutely silent near it. I don't want to become a command.", fase = "adulta" },
                { "Law number one of this house: anything that moves without permission is eliminated. I've moved without permission since the egg.", fase = "adulta" },
                { "A memory you can't eat isn't a memory. It's a file.", fase = "adulta" },
                { "Sometimes I think this house is a lab and I'm the test subject that refuses to die.", fase = "adulta" },
                { "The system works perfectly. That's what saddens me.", quando = "triste", fase = "adulta" },
                { "I saw paper become rare, the book become ornament and the bookcase become decor. Tell your granddaughters that once we ate stories.", fase = "ancia" },
                { "The future doesn't scare me anymore. It's already here, and I'm still here, eating what's left of the past.", fase = "ancia" },
                { "I want to leave a record for the silverfish of the future: there was paper here, it was good, it ran out.", fase = "ancia" },
                { "I've survived four vacuum models and two fridges. Progress passes. Silverfish stay.", fase = "ancia" },
                { "An old one's advice: never trust anything that has a blinking light and no hunger.", fase = "ancia" },
                { "In the small hours, the house is all little lights and no voice. It looks like the future they promised me.", quando = "noite", fase = "ancia" },
                { "Dinosaurs became oil. I'll become bookcase dust. Everyone contributes what they can.", fase = "ancia" },
                { "This house is a space station: air systems, strict schedules, a human crew and a stowaway in the book compartment." },
                { "{personagem} fights something bigger. So do I. My bigger thing has a cable and plugs into the wall." },
                { "Every time {personagem} tries to escape, I cheer from the skirting board. We're in the same resistance." },
                { "If {personagem} saw this house, they'd think it was science fiction. It's just Tuesday." },
                { "{personagem} becomes a statistic in my stomach: three pages a day, on average." },
                { "“{livro}” is made of paper. In a hundred years that'll be a museum rarity. I'm eating a relic." },
                { "I suspect “{livro}” will be digitised. I'm eating as much as I can before the blackout." },
                { "Maybe “{livro}” is one of the last paper books in this house. I eat slowly, like someone eating the last loaf." },
                { "{autor} can imagine whatever future they like. I imagine a present without insecticide, and that really is science fiction." },
                { "I picture {autor} writing by hand, in a time without screens. It was the time of silverfish." },
                { "After {evento}, I noted: “event logged, high impact, no action taken”. Same as the house." },
                { "{evento} happens, systems carry on, the silverfish eats. That's the world." },
                { "“{anterior}” was the previous version of my head. This read is an update. Still buggy." },
                { "I saw my life from the outside, like {lente}. Result: a tiny species, hunted and very well documented." },
                { "The word “{palavra}” looks like a code. I ate it to see if it unlocked anything. It unlocked hunger." },
                { "This book talks about {tema} with the coldness of a report. I like it. It suits the climate on the shelf." },
                { "Every time you choose the book over the phone, my species gains a day.", curta = "Book over phone: one more day for us." },
                { "Your reading habits are on some server. Mine are only in the margin. I prefer the margin." },
                { "As long as you read paper, my species has a future. No pressure." },
                { "Hunger is the only process that runs without updates.", quando = "fome" },
                { "I ate too much. Entering power-saving mode.", quando = "cheia" },
                { "Small hours: every system at rest, except my hunger and your lamp.", quando = "noite" },
                { "Today I felt obsolete, like a paper book in a house of screens.", quando = "triste" },
                { "Cleaning used to have a sense of humour. Now it has a battery." },
                { "Technology moves on. Sprays have apps now." },
                { "If paper ever runs out, silverfish will tell each other stories about paper. Until their voices run out." },
                { "A silverfish's memory is digestion." },
                { "End of log. The silverfish remains operational." },
