        -- 9. poesia e lirismo: imagem, som, condensação; o mundo dela em miniatura, com menos piada
        poesia = {
            frases = {
                { "Dust in the window light. The house snows on the inside, and only I notice.", curta = "Dust in the window light. The house snows inside." },
                { "Glue goes soft in summer. So do I." },
                { "I chew the word “{palavra}” slowly. It crackles, then dissolves, then leaves the taste of something that used to be.", fase = { "adulta", "ancia" }, curta = "Ate “{palavra}” slowly. It tasted of what was." },
                { "In “{livro}”, between the margin and the text, runs a white river. I live on the bank and fish for letters." },
                { "Everything is a first time: the first paper, the first shadow, the first fear. I want to keep a little of each before I grow.", fase = "ninfa" },
                { "Hunger at night is different: deeper, bluer, without a sound.", quando = "noite" },
                { "I'm learning to eat slowly. A good page is like the moon: bite it all at once and it goes dark.", fase = "jovem" },
                { "This book smells of {tema}. I keep the smell in the fold of the page, where I keep everything I can't say.", fase = "adulta" },
                { "Yellowed paper keeps the light of the years it was read in. So do I. That's why I shine a little, and slowly.", fase = "ancia" },
                { "There was {evento}. I kept only the sound, which is what stays after the words have gone." },
                { "Today the afternoon felt like {lente}: it began beautifully, ended without a rhyme, and I read to the end anyway." },
                { "I repeat the name {personagem} softly, again and again, until it's only sound, like a page read so often it turns white.", fase = { "ninfa", "jovem" }, curta = "I whisper {personagem} until it's only sound." },
                -- novas (rascunhos de 29/10/2026, cartoes/rascunhos/influencias)
                { "The world began white: the page. Then the letters came, like little black birds landing.", fase = "ninfa" },
                { "A page turning in the small hours: the softest sound in this house.", fase = "ninfa" },
                { "The first word I ate was “sea”. I tasted of salt for a week.", fase = "ninfa", curta = "My first word was “sea”. I turned salty." },
                { "Dust in the afternoon light: gold you can't eat.", fase = "ninfa" },
                { "My fear fits in a comma. Sometimes I sleep inside it.", fase = "ninfa" },
                { "My mother said: “eat slowly, the page is the world”. I did. It was.", fase = "ninfa" },
                { "The moon is a round page no one can eat.", fase = "jovem" },
                { "Some lines are for eating and some are for keeping. This one is for keeping.", fase = "jovem" },
                { "Library silence: the sound of letters sleeping.", fase = "jovem" },
                { "The rain writes on the window in a language I can't eat.", fase = "jovem" },
                { "The word “longing” tastes of wet paper. “Morning” tastes of soft bread.", fase = "jovem" },
                { "At night the paper goes cold, and the letters huddle like people in bed.", quando = "noite", fase = "jovem" },
                { "Today I'm as light as tissue paper in the sun.", quando = "feliz", fase = "jovem" },
                { "I moulted. The old skin stayed at the window, transparent, holding the shape of the sun.", quando = "muda", fase = "jovem" },
                { "An old page is like a face: the stains tell where life passed.", fase = "adulta" },
                { "Everything I know fits in one line. The rest is hunger.", fase = "adulta" },
                { "Life rhymes: cleaning, fleeing, feeding, cleaning.", fase = "adulta" },
                { "A silverfish grieves as quietly as a blank page.", fase = "adulta" },
                { "Every season has a different book smell. This one smells of goodbye.", fase = "adulta" },
                { "A good afternoon is one where nothing happens and the light stays.", fase = "adulta", curta = "A good afternoon: nothing happens, light stays." },
                { "Some words melt in the mouth like snow. They leave only a wish for more winter.", fase = "adulta" },
                { "Sadness is a wet page that dries crooked.", quando = "triste", fase = "adulta" },
                { "I was new silver once. Now I'm worn silver, like the family cutlery.", fase = "ancia" },
                { "I remember one winter afternoon when the sun stayed on the bookcase till late. Just that. It's enough.", fase = "ancia" },
                { "I want to leave the way a leaf falls: without a sound, after being beautiful.", fase = "ancia" },
                { "Old at last, I understand the blank space on the page.", fase = "ancia" },
                { "I tell the young ones: beauty lives in the corner of the page, where nobody looks.", fase = "ancia" },
                { "In the small hours, the whole house becomes a poem: dark, short and full of pauses.", quando = "noite", fase = "ancia" },
                { "May the next silverfish inherit my habit of stopping in the light.", fase = "ancia" },
                { "A crumb on the rug shines like a gemstone at five in the afternoon." },
