        -- 10. tragédia: destino, queda, ironia trágica; ela sabe o fim e assiste mesmo assim
        tragedia = {
            frases = {
                { "I knew the broom would come. I knew the day, the hour and the corner. Knowing never saved anyone; it just lets you watch in more detail.", fase = { "adulta", "ancia" }, curta = "I knew when the broom would come. I just watched." },
                { "My fatal flaw is a taste for good paper. Good paper lives on clean shelves, clean shelves have careful owners, and careful owners have insecticide.", curta = "My fatal flaw: a taste for good paper." },
                { "I don't know how it ends for {personagem}. But I know the genre, and the genre doesn't forgive anyone who shows up this much." },
                { "There was {evento}. If this book had a chorus, it would say it had warned them. I'm the chorus. I warned them. Nobody listens to silverfish." },
                { "I escaped the insecticide and fell into the mothballs. The gods have a sense of humour, and it's always at my expense.", fase = { "ninfa", "jovem" }, curta = "From insecticide to mothballs. The gods laugh." },
                { "My mother told me every silverfish has a last page. I asked which one would be mine. She changed the subject, and I understood.", fase = "ninfa" },
                { "I climbed to the highest shelf just to prove I could. From up there you can see everything, including the hand coming down.", fase = "jovem" },
                { "Every author builds the fall slowly, and {autor} is probably no exception. I recognise the method: it's the same as the end-of-year cleaning.", fase = "adulta" },
                { "I'm reaching the last act. I already know the ending, I've forgiven almost everyone, and I still haven't forgiven the broom.", fase = "ancia" },
                { "Everything I do to survive makes me more visible. There's a name for that: {lente}." },
                { "“{livro}” will end, I'll eat the last page, and someone will call it damage, not an ending." },
                { "This book has been heading towards {tema} since the first page, and everyone pretends to be surprised. I don't pretend. I live at the end of books." },
                { "Starving to death in a library. Good epitaph." },
                -- novas (rascunhos de 29/10/2026, cartoes/rascunhos/influencias)
                { "My mother cried when I was born. She said it was joy. She lied. It was knowledge.", fase = "ninfa" },
                { "An ancient silverfish read my future in the pattern of the mould. She only told me to eat while I can.", fase = "ninfa" },
                { "My first mistake was liking the light. Every silverfish makes that mistake once. Some only once.", fase = "ninfa" },
                { "My brother loved the window. The window didn't love him back.", fase = "ninfa", curta = "My brother loved the window. Not vice versa." },
                { "I thought the bookcase was the whole world and the whole world was safe. First illusion.", fase = "ninfa" },
                { "The old silverfish always warn: “don't go”. Nobody listens. That's why they're old and the others aren't.", fase = "ninfa" },
                { "I bragged about facing the cat. The following week, it reminded me who's in charge.", fase = "jovem" },
                { "I know my flaw will kill me: curiosity. Knowing that, I stay curious. That's tragedy too.", fase = "jovem" },
                { "I found the perfect hiding place: a closed box. It was the donation box.", fase = "jovem" },
                { "She lives on the shelf of light. I live on the shelf of shadow. In tragedy, love always lives far away.", fase = "jovem" },
                { "I ignored the first warning, the second and the third. By the fourth, it was too late for warnings.", fase = "jovem" },
                { "Small hours: the time when every ending becomes obvious.", quando = "noite", fase = "jovem" },
                { "Complete happiness. I know: it's the scene before the third act.", quando = "feliz", fase = "jovem", curta = "Pure happiness. Here comes the third act." },
                { "New skin, old fate.", quando = "muda", fase = "jovem" },
                { "I already know the end of almost everything. It doesn't save me from anything. It just gets me a better seat.", fase = "adulta" },
                { "Now I'm the one who warns the young. They don't listen. We become the chorus, which is what's left of those who've seen too much.", fase = "adulta" },
                { "Every time a silverfish thinks she's immortal, I move my antenna out of the way and wait.", fase = "adulta" },
                { "I tried changing books to escape fate. Fate changed books with me.", fase = "adulta" },
                { "Every tragedy has someone to blame. Sometimes it's fate. Sometimes it's me.", fase = "adulta" },
                { "I've already chosen my last line. I won't tell. A silverfish needs some suspense.", fase = "adulta" },
                { "The bookcase is a wooden stage with a demolition date.", fase = "adulta" },
                { "Sad like a chorus nobody applauds.", quando = "triste", fase = "adulta" },
                { "At my age, every day is an extra act the author forgot to cut.", fase = "ancia" },
                { "Wisdom arrives like letters in tragedies: after the funeral.", fase = "ancia" },
                { "I've forgiven the cat, the vacuum and the damp. Not the broom. Every tragedy needs one grudge that stays.", fase = "ancia" },
                { "I know I'll end up on some page, flattened between two words. I hope they're at least beautiful ones.", fase = "ancia" },
                { "The chorus in tragedies is always the old ones. Now I understand why.", fase = "ancia" },
                { "Long night, the end close. I listen to the house the way you hear your own heart in the last act.", quando = "noite", fase = "ancia" },
                { "I want to die eating. It's the only dignified end for a silverfish.", fase = "ancia", curta = "I want to die eating. A worthy end." },
                { "This house is a stage: the bookcase is the set, the broom is fate and I'm the extra who insists on having a line." },
                { "Every time {personagem} believes it'll work out, I eat more slowly. To postpone." },
                { "I want to warn {personagem}. Silverfish always want to warn. Nobody listens to silverfish." },
                { "My heart sinks every time {personagem} smiles. I know the genre." },
                { "If {personagem} knew what I know about books, they'd stop reading." },
                { "Since the first page of “{livro}”, I've smelled the ending. That's how you recognise a tragedy." },
                { "The irony of “{livro}” is that everyone sees the disaster coming except whoever will suffer it." },
                { "Eating “{livro}” is slowly eating a sentence." },
                { "I admire {autor} for the calm cruelty. The best tragedies are written with patience." },
                { "{autor} saves no one. But doesn't abandon anyone either." },
                { "{evento}: the first step of a staircase that only goes down." },
                { "After {evento}, someone said “now it'll work out”. I stopped eating." },
                { "I finished “{anterior}” in tears. This one is going the same way, and I'm going with it." },
                { "I saw today's cleaning as {lente}: an ending everyone predicted and no one prevented." },
                { "“{palavra}” appears again. In tragedies, the returning word is fate knocking at the door." },
                { "Every story about {tema} ends the same way. I read to see how long each one takes." },
                { "I saw you stop before the last chapter. I stop too. Some pages you don't want to eat." },
                { "I feel your hand grip the cover when the story gets worse. We're the same audience." },
                { "You don't know yet. I do. It's hard being the silverfish who knows." },
                { "I'm hungry. I know where the food is. I also know who guards it. I'm going anyway.", quando = "fome" },
                { "Full belly, guard down. Tragedies love that combination.", quando = "cheia" },
                { "Night comes down like a curtain over the bookcase. No one applauds.", quando = "noite" },
                { "Sad like someone who has already read the last chapter.", quando = "triste" },
                { "The broom isn't evil. It's fate with a wooden handle. It does what it has to do." },
                { "The silverfish who laughs at the broom is always the first to be swept away." },
                { "Here lies a silverfish who knew the ending and ate until she got there." },
                { "Tragedy isn't a surprise. It's repetition with new pain." },
                { "I know how it ends. I stay till the end. That's what sets us apart from the chairs." },
                -- fim das novas
            },
            lentes = { "a fall foretold", "a third act with no interval", "a fatal flaw" },
            fechos = { "It was written.", "The chorus already knew.", "And there was no way out." },
        },
        -- 11. realismo social: classe, trabalho, quem é dono da estante e quem limpa depois
        social = {
            frases = {
                { "Expensive books live in the glass bookcase. Cheap books live in the box in the garage, under the leak. I live in the garage: the food is worse, but nobody pretends it's culture." },
                { "Whoever binds doesn't read, whoever reads doesn't own, whoever owns doesn't read, and whoever eats gets exterminated. That's the paper food chain.", curta = "Readers don't own. Eaters get exterminated." },
                { "The glue in “{livro}” is cheap. Someone saved on my food to pay for the glossy cover. They always save on what doesn't show." },
                { "I work all night, no wages, no holidays, no light, and when they find me they call me a parasite. A parasite is someone with thirty books who reads one.", fase = { "adulta", "ancia" }, curta = "A parasite owns thirty books and reads one." },
                { "{autor} signed the book and kept the name. Whoever sewed, glued and carried the boxes doesn't appear on any page. I eat in their honour." },
                { "I keep wondering who washed the clothes of {personagem}. No book says. Other people's hunger always stays at the back of the scene." },
                { "I learned early: the top shelf is for the beautiful books, and the bottom one is for what's left over. I was born on the bottom one. It's a start.", fase = "ninfa", curta = "Born on the bottom shelf. It's a start." },
                { "I tried to organise the silverfish in the garage. Agenda: damp, food and the right to exist without spray. Nobody came. They were all working.", fase = "jovem" },
                { "This book talks a lot about {tema}. I'd like to know who paid for the paper, who carried the boxes and who cleaned up afterwards.", fase = "adulta" },
                { "I've seen this house change owners three times. The owners took the paintings and left the books. Nobody ever takes the silverfish; we come free with the house.", fase = "ancia" },
                { "There was {evento}. I bet whoever cleaned up afterwards doesn't appear on any page, not even in a footnote." },
                { "They called it a big clean. I'd call it {lente}: they decided for us, without asking, and thought they were doing us a favour." },
                { "Insecticide costs less than a book. Do the maths and tell me who's worth more in this house." },
                -- novas (rascunhos de 29/10/2026, cartoes/rascunhos/influencias)
                { "I was born in the garage box, among old newspapers and a leak. The silverfish of the glass bookcase were born in another world.", fase = "ninfa" },
                { "On the bookcase, expensive books sit at eye level. Cheap ones sit on the floor, near the broom. Same as outside.", fase = "ninfa" },
                { "My mother raised thirty daughters in a newspaper box. Nobody wrote about it.", fase = "ninfa" },
                { "I'd barely hatched before I went to fetch food. There's no childhood in the garage box.", fase = "ninfa" },
                { "The silverfish upstairs have family names. The ones downstairs only have hunger.", fase = "ninfa", curta = "Up top, surnames. Down here, hunger." },
                { "I found out that the very thing that feeds my family is called “damage” by the owners.", fase = "ninfa" },
                { "I called an assembly in the newspaper box. Three silverfish and a mite came. We passed everything unanimously. Nothing changed.", fase = "jovem" },
                { "Now I understand why the broom always goes over the same spot: the skirting board is the outskirts of the house.", fase = "jovem" },
                { "Night shift on the bookcase: eat, hide, keep watch. Nobody pays overtime to a silverfish.", fase = "jovem" },
                { "Garage hunger is different from bookcase hunger. One is lack. The other is choice.", fase = "jovem" },
                { "I'm angry at the glass bookcase. Not at the silverfish in it. At the glass.", fase = "jovem" },
                { "Night is the shift of those who have no choice.", quando = "noite", fase = "jovem" },
                { "Today we found a forgotten box of books. Food for the whole garage for a month. Nobody ate alone.", quando = "feliz", fase = "jovem" },
                { "I moulted without stopping work. Nobody gives a silverfish time off to grow.", quando = "muda", fase = "jovem" },
                { "I've understood the economics of this house: the book is an asset, the reader is a customer and the silverfish is a loss.", fase = "adulta", curta = "Books are assets. We are losses." },
                { "Nobody sees whoever cleans the house at six in the morning. I do. We're the invisible work around here.", fase = "adulta" },
                { "The owners talk about books the way they talk about property: they value, invest, keep.", fase = "adulta" },
                { "The owner inherited grandpa's library and never opened a book. I inherited the garage and read everything.", fase = "adulta" },
                { "Humans call it a donation. We call it an eviction.", fase = "adulta" },
                { "Every book has a factory behind it, a print shop and someone on the night shift. The cover only has one name.", fase = "adulta" },
                { "Alone, a silverfish changes nothing. Together, we've already moved three boxes.", fase = "adulta" },
                { "Sad like a strike nobody noticed.", quando = "triste", fase = "adulta" },
                { "I've worked my whole life and I still live in the skirting board. I'm not complaining. I'm keeping a record.", fase = "ancia" },
                { "I took part in three attempts to occupy the glass bookcase. On the last one we won a shelf. It was worth it.", fase = "ancia" },
                { "The owners changed, the bookcases changed, the insecticides changed. Inequality stays in the same place: top to bottom.", fase = "ancia" },
                { "An old one's advice: the broom obeys someone. Find out who.", fase = "ancia" },
                { "I own nothing, but I have dignity. I never ate another silverfish's crumb.", fase = "ancia" },
                { "When I can't sleep, I do the house's sums: how many books, how many silverfish, how much food. It never adds up.", quando = "noite", fase = "ancia" },
                { "I leave one idea as my inheritance: the bookcase belongs to whoever eats it.", fase = "ancia", curta = "The bookcase belongs to its eaters." },
                { "The house has neighbourhoods: the glass bookcase is the rich centre, the garage is the outskirts, the skirting board is the squat." },
                { "Every time {personagem} has coffee, somebody made the coffee. The book forgets. I don't." },
                { "{personagem} has never had to think about food. You can taste it on the page." },
                { "Does {personagem} work in this story? If so, the book doesn't show it. It's like that with almost everyone in books." },
                { "{personagem} makes choices as if they had a choice. I know not everyone does." },
                { "The cover of “{livro}” is luxury. The pages are economy class. Like a lot of people." },
                { "The price of “{livro}” is printed on the back. The price paid by whoever made it, nowhere." },
                { "“{livro}” lives on the middle shelf. Middle-class book: neither shop window nor box." },
                { "{autor}'s name is on the cover in big letters. The proofreader's is in small print inside. The printer's, nowhere." },
                { "I thank {autor} for looking down. Few do." },
                { "{evento}, and still someone had to serve dinner." },
                { "There was {evento}, and the ones who paid were the ones who always pay." },
                { "After “{anterior}”, I learned to look for who's working in the background of every scene." },
                { "The living room renovation was {lente}: nobody who lives on the bookcase was consulted." },
                { "“{palavra}” is a word for someone who has never carried a box." },
                { "Talking about {tema} is easy when you have a house. I read from down here, where the subject arrives with a leak." },
                { "You read after a whole day's work. I know what that costs." },
                { "You lend books. In this house, that's almost revolutionary." },
                { "You share books, I share crumbs. Each class with its own solidarity." },
                { "I'm hungry, and the glass bookcase is full. That isn't nature. It's organisation.", quando = "fome" },
                { "Full belly today. I'll save the rest for my sisters in the garage.", quando = "cheia" },
                { "Small hours: the time of the invisible workers. I greet the others with an antenna.", quando = "noite" },
                { "Sad like a box of books going to the bin with a family inside.", quando = "triste" },
                { "The broom isn't to blame. It's a tool. I always ask who ordered the sweeping." },
                { "Every book went through a print shop, and at the print shop someone was on shift. The smell of ink still keeps the tiredness." },
                { "The house spends more on silverfish poison than on new books. The priorities speak for themselves." },
                { "If the bottom shelf falls, the whole bookcase falls. Nobody remembers that at the meetings." },
                { "The word “pest” was invented by those who had something to protect.", curta = "Pest: a word for those with things to guard." },
                -- fim das novas
            },
            lentes = { "an eviction without notice", "a matter of class", "an unpaid extra shift" },
            fechos = { "Someone always pays the bill.", "And whoever cleans up never appears.", "Ask who profits from this." },
        },
        -- 12. existencialismo e absurdo: existir sem ter escolhido, a liberdade que assusta, o gesto repetido
        existencial = {
            frases = {
                { "I eat books to live and live to eat books. Someone should review this project, and the only employee available is me.", curta = "I live to eat and eat to live. Some project." },
                { "I'm free to go to any corner of the bookcase. That's exactly what scares me: no corner was made for me.", fase = { "ninfa", "jovem" }, curta = "I can go to any corner. None of them is mine." },
                { "I woke up a silverfish. I don't remember choosing it. Nobody asked if I wanted antennae, and now I have to use them.", fase = "ninfa" },
                { "Every day I push the same crumb to the crack, and every day it ends up back in the middle of the room. Maybe I'm happy like this. It's what there is to be.", fase = { "adulta", "ancia" }, curta = "The same crumb every day. Maybe I'm happy." },
                { "Sometimes I stop in the middle of “{livro}” and ask: why this page? Why me? Why glue? Then I eat, which is the only answer that occurs to me." },
                { "{personagem} makes choices all the time, as if they weighed something. I choose too: left or right of the spine. Neither one saves me." },
                { "I'm tired of looking for meaning. I'll look for food, which at least turns up now and then.", fase = "jovem" },
                { "There was {evento}, and the universe stayed indifferent. So did I, out of solidarity. It isn't coldness; someone has to keep eating.", fase = "adulta" },
                { "I've lived so long I've made the same mistakes with different convictions. They call it maturity. I call it a second reading.", fase = "ancia" },
                { "I woke up and the day already looked like {lente}. I ate anyway. Hunger doesn't need a reason." },
                { "This book revolves around {tema} as if that were the centre. For me, the centre is where the glue is thickest." },
                { "I finished “{anterior}” and didn't change at all. I thought I would. Maybe that's the change." },
                -- novas (rascunhos de 29/10/2026, cartoes/rascunhos/influencias)
                { "I hatched and my first question was “why?”. The second was “what's to eat?”. The second won.", fase = "ninfa" },
                { "I looked at the blank page and it looked at me. Neither of us knew what to say.", fase = "ninfa" },
                { "My mother said: “Go wherever you like.” I stood still in the same spot for an hour.", fase = "ninfa" },
                { "I started counting how many times I take the same path. I lost count on Tuesday.", fase = "ninfa" },
                { "Sometimes I stop in the middle of the page, not hungry, not afraid, just existing. It's worse than fear.", fase = "ninfa" },
                { "I asked the oldest silverfish what the meaning of life was. She said: “Eating.” I asked what the meaning of eating was. She went to sleep.", fase = "ninfa" },
                { "I looked for the meaning of life in the index. It wasn't there. I looked in the glossary. Not there either.", fase = "jovem" },
                { "I chose to eat the dedication. Nobody told me to. It's the first thing I've done just because I wanted to.", fase = "jovem" },
                { "I flee the broom to go on existing, to go on fleeing the broom.", fase = "jovem", curta = "I flee the broom to keep fleeing it." },
                { "I look at my reflection and think: who decided I'd be this?", fase = "jovem" },
                { "I ate a whole book in one go and felt nauseous. Not from the paper. From the world.", fase = "jovem" },
                { "At three in the morning, the questions get louder.", quando = "noite", fase = "jovem" },
                { "I'm happy. I don't know why. I don't know why I get sad either. A draw.", quando = "feliz", fase = "jovem" },
                { "The new skin didn't come with instructions. It never does.", quando = "muda", fase = "jovem" },
                { "I've understood that life is repetition. The choice is what face to wear.", fase = "adulta" },
                { "Meaning doesn't come ready-made. It's like a nest: you gather crumbs until it looks like home.", fase = "adulta" },
                { "Everything I do is my choice. I can't blame the broom for me leaving the hiding place.", fase = "adulta" },
                { "Hell is other silverfish eating my margin.", fase = "adulta", curta = "Hell is other silverfish." },
                { "The universe doesn't care about silverfish. I care about the universe. An unequal relationship.", fase = "adulta" },
                { "The broom passes, the dust comes back. Nobody gives up. That moves me.", fase = "adulta" },
                { "Sometimes I pretend I'm just a silverfish, so I don't have to think. But I'm a silverfish who thinks.", fase = "adulta" },
                { "Sad like a blank page nobody will ever write on.", quando = "triste", fase = "adulta" },
                { "I've read my life twice. The second time, I understood less and liked it more.", fase = "ancia" },
                { "At my age, the lack of meaning is an old acquaintance. We have tea together.", fase = "ancia" },
                { "Death gives meaning to nothing. It just closes the book.", fase = "ancia" },
                { "Old, finally free: I'm no longer afraid of getting it wrong. I've got everything wrong already.", fase = "ancia" },
                { "I tell the nymphs: don't look for meaning. Make one. With crumbs, if need be.", fase = "ancia" },
                { "Long night. I exist. I don't know what for. Still, I exist with relish.", quando = "noite", fase = "ancia" },
                { "My last gesture will be like all the others: a bite. There's consistency in that.", fase = "ancia" },
                { "I live in a place that wasn't made for me. That's the definition of existing." },
                { "I admire {personagem} for choosing without knowing the outcome. It's the only way to choose." },
                { "If {personagem} knew they were a character, they'd ask the same questions I ask." },
                { "{personagem}'s life is absurd. So is mine. At least {personagem} has a plot." },
                { "Others decide who {personagem} is. Same with me: they've decided I'm a pest." },
                { "“{livro}” has a beginning, a middle and an end. My life only has a middle.", curta = "My life only has a middle." },
                { "I read “{livro}” like someone pushing a boulder uphill: page by page, knowing that at the end it starts again." },
                { "I could stop reading “{livro}” right now. Nobody's making me. I carry on. That scares me a little." },
                { "{autor} created characters who exist without having asked to. Like me. We're relatives by creation." },
                { "{autor} wrote a whole book so as not to answer. I eat a whole book so as not to ask." },
                { "{evento} happened and nobody explained why. That's how it is in the book and on the shelf." },
                { "{evento} for no reason at all. The most realistic thing in the book so far." },
                { "After “{anterior}”, I thought I'd understood everything. This book gave me my questions back." },
                { "My life, seen up close, looks like {lente}. Seen from afar, it looks like a silverfish." },
                { "“{palavra}” exists without knowing why. Just like me." },
                { "This book takes {tema} seriously. I take the next bite seriously." },
                { "Every night you choose reading over sleep. I choose eating over running. We're consistent in the absurd." },
                { "Your reading routine is my clock. Without it, the days would all be the same. With it, too, but with pages." },
                { "Maybe reading has no meaning. But you read, and I eat, and the house feels less empty." },
                { "Hunger: the most honest absurdity.", quando = "fome" },
                { "I ate a lot. Tomorrow I'll be hungry again. It's the myth of the silverfish pushing the page.", quando = "cheia" },
                { "In the small hours, the house stops pretending to make sense.", quando = "noite" },
                { "Today existing weighed more than the whole spine.", quando = "triste" },
                { "The broom comes every Friday. The dust comes back every Monday. Nobody gives up. Sisyphus with a wooden handle." },
                { "A world of seven shelves is small for so many questions." },
                { "I don't know who I am. I know what I eat. Maybe that's enough." },
                { "A silverfish's freedom: choosing the corner where she'll hide." },
                { "I don't know where I'm going. I carry on. It's the only verb I know well." },
                { "Living is pushing the crumb knowing it comes back. One must imagine the silverfish happy." },
                -- fim das novas
            },
            lentes = { "a well-organised absurdity", "a choice without a reason", "a routine without meaning" },
            fechos = { "So what.", "I carried on, for lack of options.", "Nothing changed, and that's an answer too." },
