        -- 13. filosofia e metafísica: as grandes perguntas, sempre puxadas de volta para a boca e a migalha
        filosofia = {
            frases = {
                { "If I eat a sentence, does it still exist somewhere? I ask for philosophical reasons, and digestive ones.", curta = "Does an eaten sentence exist? Ask my stomach." },
                { "Am I the same silverfish as yesterday? I changed skin, book and opinion. Only the hunger stayed the same; maybe I am the hunger.", fase = { "jovem", "adulta" }, curta = "New skin, new opinions. The hunger stayed." },
                { "Everything I know about “{livro}” I know through my mouth. It's a limited method of knowledge, but nobody can say I didn't go deep." },
                { "Does “{livro}” exist when nobody is reading it? For me it mostly exists then, because that's when I have dinner." },
                { "Philosophers spend their lives arguing about {tema}. I spend mine looking for the next meal. In the end, everyone knows the same: very little." },
                { "Today I found out there's a 'me'. Right after, I found out there's an 'out there'. I got scared of both and went to eat.", fase = "ninfa" },
                { "I started reading philosophy to understand the world. So far I've understood that the world doesn't understand either, but it writes very well about it.", fase = "jovem" },
                { "If {autor} asked me what truth is, I'd say: the part of the book nobody has eaten yet. It's not a good answer, but it's testable.", fase = "adulta" },
                { "The older I get, the fewer certainties and the more pages in my stomach. There must be a link between the two, but I'm too tired to prove it.", fase = "ancia", curta = "More paper in my belly, fewer certainties." },
                { "What is “{palavra}”, after all? I ate the whole word and still don't know. Maybe the meaning stays on the paper and only the taste reaches me." },
                { "I thought about my life as {lente}. I reached a deep conclusion and, right after, a crumb. I kept the crumb." },
                { "I think, therefore I hide." },
                -- novas (rascunhos de 29/10/2026, cartoes/rascunhos/influencias)
                { "First philosophical question: if I weren't here, would the page be the same? First answer: probably more complete.", fase = "ninfa" },
                { "I ate the word “tree” and saw no tree at all. Where does the thing go when the word disappears?", fase = "ninfa" },
                { "Yesterday I was an egg. Today I'm a nymph. Where does yesterday live?", fase = "ninfa" },
                { "The bookcase looks infinite. I counted the books and it ended at thirty-two. Infinity has a shelf.", fase = "ninfa" },
                { "Learning is eating slowly. Forgetting is digesting.", fase = "ninfa" },
                { "I think the truth is in the middle of the book. Covers lie.", fase = "ninfa" },
                { "My philosophical method: doubt everything except hunger.", fase = "jovem" },
                { "I live in a cave: the spine. I see the shadows of humans on the wall and think they're the world. Maybe they are.", fase = "jovem" },
                { "Did the page I ate stop existing, or did it start existing in me?", fase = "jovem" },
                { "What if the bookcase is another silverfish's dream? I bite the spine to check. It hurts. It's real. Or it's a good dream.", fase = "jovem" },
                { "If every silverfish ate like me, would any book be left? Kant would be disappointed in me.", fase = "jovem" },
                { "At three in the morning, I wonder whether the house exists when nobody's awake. I am. So it exists a little.", quando = "noite", fase = "jovem" },
                { "I had an epiphany on the spine. It lasted as long as a crumb. Worth it.", quando = "feliz", fase = "jovem" },
                { "Moulting: the most concrete philosophical problem I know.", quando = "muda", fase = "jovem" },
                { "I used to have lots of answers. Now I have better questions.", fase = "adulta" },
                { "The past is in the margin I've already eaten. The future, in the one I haven't. The present is the bite.", fase = "adulta", curta = "The present is the bite." },
                { "I'm free to eat any book. But I only eat the ones within reach. Is that freedom or geography?", fase = "adulta" },
                { "Beauty, to me, is cotton paper at four in the afternoon.", fase = "adulta" },
                { "Do I have a soul? If I do, it must taste of glue.", fase = "adulta" },
                { "Silverfish epistemology: I only know what I've eaten.", fase = "adulta" },
                { "Philosophers write for the centuries. I eat for today.", fase = "adulta" },
                { "Some days thinking tires me more than running.", quando = "triste", fase = "adulta" },
                { "In old age, I found out that wisdom is knowing you know little. It took my whole life to know little.", fase = "ancia" },
                { "Death is the only question that answers itself.", fase = "ancia" },
                { "I've been egg, nymph, young, adult. Am I the same? I think I'm one long sentence.", fase = "ancia" },
                { "The philosophy of old age is short: eat slowly and don't argue with the broom.", fase = "ancia" },
                { "I tell the nymphs: ask everything, but don't forget to eat. Metaphysics doesn't feed you.", fase = "ancia" },
                { "Long night. I think about being, nothingness and damp.", quando = "noite", fase = "ancia" },
                { "My inheritance is a well-kept doubt.", fase = "ancia" },
                { "The bookcase is my universe. It has order, it has chaos and it has a law of gravity called the broom.", curta = "Here, the law of gravity is called broom." },
                { "{personagem} asks the same questions I do: who am I, where am I going. The difference is they have an author to answer." },
                { "{personagem} chose the hard path. Respect. I always choose the path with more glue." },
                { "If the book ends, does {personagem} stop existing? Or wait for the next reading?" },
