                { "Some days philosophy is just a polite form of insomnia.", quando = "triste" },
                { "Against the broom, philosophy has no argument. Only escape." },
                { "Every page is a tree that changed its mind." },
                { "I'm made of everything I've eaten. So I'm a little of every book in this house. A library with antennae.", curta = "I'm a library with antennae." },
                { "From the skirting board, the universe looks bigger. That's a philosophical advantage." },
