        niilismo = {
            frases = {
                { "They promised “{livro}” would change lives. So far it has changed its place on the shelf and my menu." },
                { "Grand explanations usually have small print in the footnotes. I eat the footnotes first, to find out the price.", curta = "Footnotes first. That's where the price is." },
                { "Values change from century to century. The price of insecticide only goes up.", fase = { "adulta", "ancia" }, curta = "Values come and go. Poison only gets pricier." },
                { "I don't believe in happy endings. I believe in endings.", fase = { "adulta", "ancia" } },
                { "They say literature saves. I live inside a book by {autor}, and I've lost three sisters to mould." },
                { "If {personagem} is sure of anything, I'll doubt it twice over. Certainty is the first thing to go mouldy." },
                { "They told me that if I was good, nothing bad would happen to me. I've seen the broom sweep over good silverfish. I started doubting early.", fase = "ninfa" },
                { "I went through a phase of believing in nothing. It lasted all morning. Then a page of glossy paper turned up, and I relapsed into faith.", fase = "jovem", curta = "Nihilist until lunch. Then, glossy paper." },
                { "There was {evento}. Humans call that a lesson. I call it Tuesday.", fase = "adulta" },
                { "I've seen revolutions become bookcases, bookcases become firewood and firewood become memories. I believe in nothing, but I keep everything, which is the old way of believing.", fase = "ancia" },
                { "They offered me meaning in the shape of {lente}. I politely declined. I already have somewhere to keep my hunger." },
                { "This book swears that everything depends on {tema}. I've heard that from other books, about other things. They all got eaten the same way." },
                -- novas (rascunhos de 29/10/2026, cartoes/rascunhos/influencias)
                { "They told me the world was good. At that very moment, the vacuum went past.", fase = "ninfa", curta = "They said the world was good. Then: vacuum." },
                { "They promised me good paper. Glossy paper came. I start out sceptical.", fase = "ninfa" },
                { "I asked what good is. They said: paper. I asked what evil is. They said: broom. The morality of this house comes from the cleaning cupboard.", fase = "ninfa" },
                { "Every grand explanation has a hole in the middle. I live in the holes.", fase = "ninfa" },
                { "I was born believing everything. It lasted until the first whiff of insecticide.", fase = "ninfa" },
                { "I believe in nothing, but I keep a crumb for tomorrow. Distrust doesn't cure hunger.", fase = "ninfa" },
                { "Today I woke up believing in nothing. I ate anyway. Hunger is the last belief.", fase = "jovem" },
