                { "Small hours: the time when all the day's promises look like lies.", quando = "noite", fase = "jovem" },
                { "Today I'm happy. I'm suspicious. But I'm not giving it back.", quando = "feliz", fase = "jovem" },
                { "Moulting: proof that everything changes and nothing improves.", quando = "muda", fase = "jovem" },
                { "Every generation swears it found the truth. Every generation gets swept up the same way.", fase = "adulta" },
                { "Literature saves no one. But it's a good place to wait for the end.", fase = "adulta" },
                { "I distrust anyone who is certain. Even more anyone who is certain about me.", fase = "adulta" },
                { "I've lost so many illusions that I collect them now. I keep them in a matchbox, in the corner of the drawer.", fase = "adulta" },
                { "Kindness doesn't protect you from spray. I learned that early.", fase = "adulta" },
