        -- 15. mito e folclore: a tradição oral da espécie, superstição, "contam que"
        mito = {
            frases = {
                { "They say the first silverfish was born from a drop of glue that fell from the moon onto a book left open. That's why we eat at night: to return the visit." },
                { "My grandmother used to say that whoever eats the last page of a book becomes a library ghost and spends eternity correcting typos.", fase = { "ninfa", "jovem" }, curta = "Granny: eat the last page and you'll haunt it." },
                { "Never sleep inside “{livro}” on a full-moon night. Family superstition. Nobody remembers why, and that's why it works." },
                { "There's a white silverfish that only appears to those about to be squashed. I haven't seen her yet. Sometimes I think it's she who hasn't seen me.", curta = "Haven't seen the white silverfish. Or she me." },
                { "{personagem} already has the look of a legend. In my species, whoever shows up that much ends up as a bedtime story, or one to scare nymphs." },
                { "There was {evento}. Where I come from, that calls for three laps of the spine, a buried crumb and silence until the next chapter." },
                { "The old silverfish say the Great Binder sewed the world with a single thread. I asked who was holding the needle. They sent me to bed.", fase = "ninfa" },
                { "I'm collecting the family legends in a notebook nobody will read. Or rather: that someone will eat, which is how we publish.", fase = "jovem" },
                { "Humans say {autor} invented this story. In my species, we know better: nobody invents a story; someone just eats it first.", fase = "adulta" },
                { "Now I'm the one who tells the legends to the nymphs, on cleaning nights. I change them a little each time. That's how a legend stays alive.", fase = "ancia", curta = "I'm the old one with the legends. I exaggerate." },
                { "In my family, what happened today would be told as {lente}. By the third generation, it would have a dragon." },
                { "This book talks about {tema} the way the old ones of my kind talk about the vacuum cleaner: quietly, and with respect." },
                -- novas (rascunhos de 29/10/2026, cartoes/rascunhos/influencias)
                { "The first story I heard was about the Silverfish Who Ate the Moon. They say that's why the moon has holes. I believed it at once.", fase = "ninfa" },
                { "If a silverfish crosses your path on the left, it means rain. On the right, cleaning. Never cross.", fase = "ninfa", curta = "Silverfish on the right: cleaning. Never cross." },
                { "Every nymph in the family is given a word to protect. Mine is “fireplace”. I don't know what it is yet.", fase = "ninfa" },
                { "The aunts talk about the Glue Beast, who lives in old spines and glues lazy silverfish in place forever.", fase = "ninfa" },
                { "I asked Granny why we're afraid of light. She told a long story about a sun that burned a whole generation. Now I'm afraid of the sun.", fase = "ninfa" },
                { "They told me eating the word “end” brings bad luck. I always skip it.", fase = "ninfa" },
                { "I've written down twenty legends. The vacuum cleaner is the monster in ten of them. Makes sense.", fase = "jovem" },
                { "They say the vacuum is a dragon that lost its wings and now can only swallow. Sometimes I feel sorry for it.", fase = "jovem" },
                { "The heroine of our legends has no sword. She has hunger and stubbornness. More realistic.", fase = "jovem" },
                { "At the full moon, the ancient silverfish dance at the edge of the window. I went to see once. There was only dust dancing. Maybe that was them.", fase = "jovem" },
                { "My amulet is a sequin I found on the rug. I don't know if it protects me. It shines, and that's something.", fase = "jovem" },
                { "In the small hours, the old ones tell scary stories. The best is the Hand from the Ceiling, which comes down when someone eats too loudly.", quando = "noite", fase = "jovem" },
                { "Today I saw three crumbs in a straight line. By tradition, it's a sign of plenty. I ate all three to make sure.", quando = "feliz", fase = "jovem" },
                { "Legend says that when you moult, the old skin takes an old fear with it. It took the one about the cat. The broom one stayed.", quando = "muda", fase = "jovem" },
                { "I've told the legend of the Great Bookbinder fifty times. In today's version, he had a moustache.", fase = "adulta" },
                { "Legends lie in the details and get the essentials right. That's why they last.", fase = "adulta", curta = "Legends lie in details, not in essence." },
                { "By tradition, the Great Bookbinder returns at the end of time to sew up the loose pages. I've loosened a few. Apologies in advance.", fase = "adulta" },
                { "Another version says we came from a library that burned down: the ashes became silverfish. I prefer this one. It has drama.", fase = "adulta" },
                { "I don't believe in superstition. But I never eat the word “end”, never sleep facing the window and always turn round three times before entering a new book.", fase = "adulta" },
                { "There's an old song about the vacuum cleaner. The only cheerful song on the bookcase: it ends with the vacuum broken.", fase = "adulta" },
